 void CitySafe(Action action){if(busy){Say("Wait for the current operation before editing setup drafts.");return;}Safe(action);}
 CitySetup ReadCity(){var d=CityCodec.Clone(cityState);d.Name=setupName.Text.Trim();d.Atmosphere=Sel(atmosphere);d.PlayerDescription=playerLook.Text.Trim();d.PlayerEnabled=playerLookOn.Checked;d.Language=Sel(lang);d.Profanity=swear.SelectedIndex;d.Endings=endingEnabled.Checked?(endingSlider.Value==0?3:endingSlider.Value==2?2:1):0;CityCodec.Validate(d);return d;}
 void ShowCity(bool preferences){loadingCity=true;try{setupName.Text=cityState.Name;for(int i=0;i<atmosphere.Items.Count;i++)if(((Choice)atmosphere.Items[i]).Value==cityState.Atmosphere)atmosphere.SelectedIndex=i;playerLook.Text=cityState.PlayerDescription;playerLookOn.Checked=cityState.PlayerEnabled;if(preferences){swear.SelectedIndex=cityState.Profanity;foreach(Choice c in lang.Items)if(c.Value==cityState.Language)lang.SelectedItem=c;endingSlider.Value=cityState.Endings==3?0:cityState.Endings==2?2:1;endingEnabled.Checked=cityState.Endings!=0;}ShowAdditions();ShowHistory();}finally{loadingCity=false;}}
 void LoadCity(bool switching=false){try{bool exists=File.Exists(Path.Combine(CityStore.Folder(root.Text.Trim()),"current.ncnsetup.json"));cityState=CityStore.Load(root.Text.Trim());ShowCity(exists);if(switching)cityEnabled.Checked=false;}catch(Exception e){cityEnabled.Checked=false;Say("Could not load setup library: "+e.Message);}}
 void ShowAdditions(string selectedId=null){var previous=additionList.SelectedItem as CityAddition;if(selectedId==null&&previous!=null)selectedId=previous.Id;additionList.Items.Clear();foreach(var a in cityState.Additions){int i=additionList.Items.Add(a);if(a.Id==selectedId)additionList.SelectedIndex=i;}}
 void ShowHistory(){historyList.Items.Clear();foreach(string f in CityStore.History(root.Text.Trim()))historyList.Items.Add(new Choice(CityStore.HistoryLabel(f),f));}
 CityAddition SelectedAddition(){var a=additionList.SelectedItem as CityAddition;if(a==null)throw new Exception("Select an addition first.");return a;}
 string SelectedHistory(){var a=historyList.SelectedItem as Choice;if(a==null)throw new Exception("Select a saved history entry first.");return a.Value;}
 void SaveCity(string action){if(busy)throw new Exception("Wait for the current operation before saving a draft.");var d=ReadCity();CityStore.Save(root.Text.Trim(),d,action);cityState=d;cityEnabled.Checked=true;ShowHistory();SavePrefs();Say("Draft saved: "+action+". Preview and Install files / prompts to update the mod.");}
 void SaveAddition(){var d=ReadCity();var selected=additionList.SelectedItem as CityAddition;var a=selected==null?new CityAddition():d.Additions.First(x=>x.Id==selected.Id);a.Name=additionName.Text.Trim();a.Text=additionText.Text.Trim();a.Enabled=additionOn.Checked;if(selected==null)d.Additions.Add(a);CityCodec.Validate(d);CityStore.Save(root.Text.Trim(),d,"Saved addition: "+a.Name);cityState=d;cityEnabled.Checked=true;ShowAdditions(a.Id);ShowHistory();SavePrefs();Say("Addition saved to draft. Install files / prompts to apply it.");}
 void ImportLook(){using(var d=new OpenFileDialog{Filter="Visible description|*.txt",Title="Load a description of V"}){if(d.ShowDialog()!=DialogResult.OK)return;if(new FileInfo(d.FileName).Length>16384)throw new Exception("Description file is too large.");string text=File.ReadAllText(d.FileName);if(text.Length>3000)throw new Exception("Use at most 3000 characters.");playerLook.Text=text;playerLookOn.Checked=true;SaveCity("Loaded player description from text file");}}
 void ExportLook(){using(var d=new SaveFileDialog{Filter="Visible description|*.txt",FileName="my-v-description.txt"}){if(d.ShowDialog()==DialogResult.OK)File.WriteAllText(d.FileName,playerLook.Text,new System.Text.UTF8Encoding(false));}}
 void ExportCity(){var d=ReadCity();if(!exportPlayer.Checked){d.PlayerDescription="";d.PlayerEnabled=false;}sharePreview.Text=CityCodec.Describe(d);using(var f=new SaveFileDialog{Filter="NightCityNet shared setup|*.ncnsetup.json",FileName="my-city.ncnsetup.json",DefaultExt="ncnsetup.json"}){if(f.ShowDialog()!=DialogResult.OK)return;File.WriteAllText(f.FileName,CityCodec.Write(d),new System.Text.UTF8Encoding(false));Say("Shared setup exported. Review authored text before publishing; history and memory are not included.");}}
 void ImportCity(){using(var f=new OpenFileDialog{Filter="NightCityNet shared setup|*.ncnsetup.json",Title="Import a shared city setup"}){if(f.ShowDialog()!=DialogResult.OK)return;var next=CityCodec.Import(f.FileName);var current=ReadCity();CityStore.Save(root.Text.Trim(),current,"Before shared setup import");if(!importPlayer.Checked){next.PlayerDescription=current.PlayerDescription;next.PlayerEnabled=current.PlayerEnabled;}CityCodec.Validate(next);CityStore.Save(root.Text.Trim(),next,"Imported shared setup as draft");cityState=next;ShowCity(true);cityEnabled.Checked=true;sharePreview.Text=CityCodec.Describe(next);SavePrefs();Say("Shared setup loaded as draft. Review the atmosphere, additions and preferences; preview/install when ready. No game files were changed by import.");}}
 }
